input.content:
import re, os, glob, sys, collections
sys.stdout.reconfigure(encoding='utf-8')
sw = set("el la los las de del que para con una un por se no es en al su sus lo como pero si sin sobre entre cuando ya más esta este esto cada todo todos o y hay puede pueden debe solo también".split())
strong = re.compile(r'[áéíóúñ¿¡]')

def score(l):
    w = re.findall(r"[a-záéíóúñ]+", l.lower())
    return sum(1 for x in w if x in sw) + (2 if strong.search(l) else 0)

res = collections.OrderedDict()
for f in sorted(glob.glob('**/*.java', recursive=True)):
    if 'build' in f.split(os.sep):
        continue
    L = open(f, encoding='utf-8').read().split('\n')
    hits = [i + 1 for i, l in enumerate(L) if score(l) >= 3 or (score(l) >= 2 and len(l) < 90 and ('//' in l or '"' in l or l.strip().startswith('*')))]
    if hits:
        res[f] = hits
out = []
for f, h in res.items():
    L = open(f, encoding='utf-8').read().split('\n')
    show = set()
    for n in h:
        show.add(n)
        for d in (-1, 1):
            j = n + d
            if 1 <= j <= len(L) and re.match(r'\s*(//|\*|/\*)', L[j - 1]):
                show.add(j)
    out.append('## ' + f.replace(chr(92), '/'))
    prev = 0
    for n in sorted(show):
        if prev and n != prev + 1:
            out.append('  ..')
        out.append(f'{n}: {L[n-1].strip()[:400]}')
        prev = n
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'hits.txt'), 'w', encoding='utf-8').write('\n'.join(out))
print(len(out))

