import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.network.chat.Component;

/**
 * <p>Se abre para todos al recibir una propuesta de descanso (ver {@link net.hawthorn.dndsheets.RestManager#propose}).
 * Aceptar o rechazar manda la respuesta; el descanso solo se aplica si TODOS aceptan.</p>
 */
public class RestVoteScreen extends ModalDialogScreen {
-----
 */
@WailaPlugin
public class JadePlugin implements IWailaPlugin {

	@Override
	public void register(IWailaCommonRegistration registration) {
		//Entity.class y no LivingEntity: un PNJ con ficha puede tener por cuerpo cualquier entidad
		//registrada (ver SheetLoader.spawnNpc), y Combatant.of ya filtra lo que no juega con reglas.
		registration.registerEntityDataProvider(StatBlock.INSTANCE, Entity.class);
	}

	@Override
	public void registerClient(IWailaClientRegistration registration) {
		registration.registerEntityComponent(StatBlock.INSTANCE, Entity.class);
	}

	/**
	 * <p>Las dos mitades del mismo dato. Van juntas a propósito: la CA y las condiciones viven en la ficha
	 * o en el NBT del monstruo, o sea <b>solo en el servidor</b> —el cliente no las tiene y no puede
	 * calcularlas—, así que hay que mandarlas explícitamente. Los PG se mandan igual aunque
	 * {@code getHealth()} sí esté sincronizado: los de este mod son los del bloque de monstruo escalados
	enum StatBlock implements IEntityComponentProvider, IServerDataProvider<EntityAccessor> {
		INSTANCE;

		private static final ResourceLocation UID = new ResourceLocation(DndsheetsMod.MODID, "stat_block");

		private static final String AC = "ac";
		private static final String HP = "hp";
		private static final String MAX_HP = "maxHp";
		private static final String TEMP_HP = "tempHp";
		private static final String CONDITIONS = "conditions";

		@Override
		public ResourceLocation getUid() {
			return UID;
		}

		@Override
		public void appendServerData(CompoundTag data, EntityAccessor accessor) {
			Combatant combatant = Combatant.of(accessor.getEntity());
			if (combatant == null) return; //Invariante 9: sin ficha ni bloque, Jade sigue como si este mod no existiera.

			data.putInt(AC, combatant.armorClass());
			data.putInt(HP, combatant.currentHp());
			data.putInt(MAX_HP, combatant.maxHp());
			data.putInt(TEMP_HP, combatant.temporaryHp());

			//Las mismas etiquetas en minúscula que ya enseñan la ficha y ConditionListScreen — este mod no
			//traduce las condiciones por clave de idioma en ningún sitio, y el HUD no va a ser el primero.
			StringJoiner labels = new StringJoiner(", ");
			for (Condition condition : combatant.conditions()) labels.add(condition.displayLabel());
			if (labels.length() > 0) data.putString(CONDITIONS, labels.toString());
		}

		@Override
		public void appendTooltip(ITooltip tooltip, EntityAccessor accessor, IPluginConfig config) {
			CompoundTag data = accessor.getServerData();
			if (!data.contains(AC)) return; //No es un combatiente de este mod, o el servidor no lo mandó.

			//Se reutilizan las etiquetas de la ficha ("AC"/"HP") en vez de abrir claves nuevas: son las
			//mismas dos palabras, y una clave nueva son 8 archivos de idioma (ver sync_lang_variants.py).
			tooltip.add(Component.translatable("gui.dndsheets.character_sheet.label_armor_class_ac")
				.append(" " + data.getInt(AC))
				.withStyle(ChatFormatting.GRAY));

			int temporary = data.getInt(TEMP_HP);
			tooltip.add(Component.translatable("gui.dndsheets.character_sheet.label_hit_points")
				.append(" " + data.getInt(HP) + "/" + data.getInt(MAX_HP) + (temporary > 0 ? " (+" + temporary + ")" : ""))
				.withStyle(ChatFormatting.GRAY));

			if (data.contains(CONDITIONS)) {
				tooltip.add(Component.literal(data.getString(CONDITIONS)).withStyle(ChatFormatting.RED));
			}
		}
	}
}

