 * en su sitio y no hay que migrar ningún pack.</p>
 */
public enum CreatureSize {
	UNKNOWN("", 1.0f),
	TINY("diminuto", 0.5f),
	SMALL("pequeno", 1.0f),
	MEDIUM("mediano", 1.0f),
	LARGE("grande", 2.0f),
	HUGE("enorme", 3.0f),
	GARGANTUAN("gargantuesco", 4.0f);

	/** Cómo se escribe en el JSON de contenido, ya normalizado (sin acentos, sin guiones, en minúscula). */
	private final String key;
	private final float spaceScale;

	//Los mismos nombres en inglés: el SRD original está en inglés y un DM puede copiar de ahí. Mismo
	//criterio que CreatureType — rechazarlos no protegería de nada, solo daría un tamaño ausente en
	//silencio. El orden es el de values().
	private static final String[] ENGLISH = {
		"", "tiny", "small", "medium", "large", "huge", "gargantuan",
	};

	CreatureSize(String key, float spaceScale) {
		this.key = key;
		this.spaceScale = spaceScale;
	}

	/** Nombre en inglés para mostrar al jugador/DM. Vacío para {@link #UNKNOWN}. */
	public String label() {
		return switch (this) {
			case UNKNOWN -> "";
			case TINY -> "Tiny";
			case SMALL -> "Small";
			case MEDIUM -> "Medium";
			case LARGE -> "Large";
			case HUGE -> "Huge";
			case GARGANTUAN -> "Gargantuan";
		};
	}

	/**
	 * <p>Cuántas veces el espacio de un Mediano ocupa esta criatura, que es el multiplicador con el que se
	 * dibuja. 1.0 significa "no la toques": es lo que devuelven {@link #UNKNOWN}, {@link #MEDIUM} y
	 * {@link #SMALL}, y por eso una criatura sin tamaño declarado se ve exactamente igual que antes de que
	 * este campo existiera (invariante 9).</p>
	 */
	public float spaceScale() {
		return spaceScale;
	}

	/** {@code UNKNOWN} si el texto está vacío o no nombra ningún tamaño — nunca falla, nunca adivina. */
	public static CreatureSize parse(String raw) {
		if (raw == null) return UNKNOWN;
		String normalized = normalize(raw);
		if (normalized.isEmpty()) return UNKNOWN;
		CreatureSize[] values = values();
		for (int i = 0; i < values.length; i++) {
			if (values[i].key.equals(normalized) || ENGLISH[i].equals(normalized)) return values[i];
		}
		return UNKNOWN;
	}

	//Acentos fuera, guiones y espacios fuera, minúsculas: "Gargantuesco", "gargantuesco" y "GARGANTUESCO"
	//son la misma palabra, y "no-muerto" enseñó en CreatureType que el guion aparece solo.
	private static String normalize(String raw) {
		String decomposed = Normalizer.normalize(raw.trim().toLowerCase(Locale.ROOT), Normalizer.Form.NFD);
		return decomposed.replaceAll("\\p{M}", "").replaceAll("[\\s_-]", "");
	}
}

