package net.hawthorn.dndsheets;

import java.text.Normalizer;
import java.util.Locale;

/**
 * <p>Las seis categorías de tamaño de 5e, más {@link #UNKNOWN} para lo que no declara ninguna. Mismo
 * molde exacto que {@link CreatureType}: enum cerrado, {@link #parse} tolerante con acentos, mayúsculas,
 * guiones y el nombre en inglés, y un valor desconocido que no dispara nada.</p>
 *
 * <p><b>Por qué existe.</b> El bestiario tiene 330 criaturas y <b>149 son mayores que Mediano</b> —102
 * Grandes, 32 Enormes, 15 Gargantuescas—, y hasta ahora ninguna se veía distinta de un aldeano: lo único
 * que el mod sabía decir del tamaño era {@code appearance.baby}, un booleano para hacer algo más pequeño.
 * Un dragón anciano y un kobold ocupaban el mismo cuerpo.</p>
 *
 * <p><b>La escala sale de la regla, no del ojo.</b> 5e no describe los tamaños en metros sino en el
 * espacio que ocupan en la cuadrícula: Diminuto 2,5 pies, Pequeño y Mediano 5, Grande 10, Enorme 15,
 * Gargantuesco 20. {@link #spaceScale()} es exactamente ese número dividido por 5, así que un Grande sale
 * al doble y un Gargantuesco al cuádruple porque el manual dice que ocupa cuatro veces más, no porque
 * quedara bonito.</p>
 *
 * <p><b>Pequeño vale 1.0 a propósito</b>, aunque un goblin sea más bajo que un humano: en 5e ocupa la
 * misma casilla de 5 pies que un Mediano. Encogerlo aquí además <b>duplicaría</b> el efecto en las
 * criaturas que ya usan {@code appearance.baby} para verse pequeñas (el goblin es justo una de ellas), y
 * saldría un goblin del tamaño de una rata. Quien quiera un Pequeño más bajo tiene ese campo, que es
 * donde esa decisión ya vivía.</p>
 *
 * <p>Solo lo consume {@link net.hawthorn.dndsheets.compat.PehkuiCompat}: <b>ninguna regla</b> pregunta hoy
 * por el tamaño. Si algún día lo hace (presa de un Grande, espacio estrecho, empujar), el dato ya está
 * en su sitio y no hay que migrar ningún pack.</p>
 */
public enum CreatureSize {
	UNKNOWN("", 1.0f),
	TINY("diminuto", 0.5f),
	SMALL("pequeno", 1.0f),
	MEDIUM("mediano", 1.0f),
	LARGE("grande", 2.0f),
	HUGE("enorme", 3.0f),
	GARGANTUAN("gargantuesco", 4.0f);

	/** Cómo se escribe en el JSON de contenido, ya normalizado (sin acentos, sin guiones, en minúscula). */
	private final String key;
	private final float spaceScale;

	//Los mismos nombres en inglés: el SRD original está en inglés y un DM puede copiar de ahí. Mismo
	//criterio que CreatureType — rechazarlos no protegería de nada, solo daría un tamaño ausente en
	//silencio. El orden es el de values().
	private static final String[] ENGLISH = {
		"", "tiny", "small", "medium", "large", "huge", "gargantuan",
	};

	CreatureSize(String key, float spaceScale) {
		this.key = key;
		this.spaceScale = spaceScale;
	}

	/** Nombre en inglés para mostrar al jugador/DM. Vacío para {@link #UNKNOWN}. */
	public String label() {
		return switch (this) {
			case UNKNOWN -> "";
			case TINY -> "Tiny";
			case SMALL -> "Small";
			case MEDIUM -> "Medium";
			case LARGE -> "Large";
			case HUGE -> "Huge";
			case GARGANTUAN -> "Gargantuan";
		};
	}

	/**
	 * <p>Cuántas veces el espacio de un Mediano ocupa esta criatura, que es el multiplicador con el que se
	 * dibuja. 1.0 significa "no la toques": es lo que devuelven {@link #UNKNOWN}, {@link #MEDIUM} y
	 * {@link #SMALL}, y por eso una criatura sin tamaño declarado se ve exactamente igual que antes de que
	 * este campo existiera (invariante 9).</p>
	 */
	public float spaceScale() {
		return spaceScale;
	}

	/** {@code UNKNOWN} si el texto está vacío o no nombra ningún tamaño — nunca falla, nunca adivina. */
	public static CreatureSize parse(String raw) {
		if (raw == null) return UNKNOWN;
		String normalized = normalize(raw);
		if (normalized.isEmpty()) return UNKNOWN;
		CreatureSize[] values = values();
		for (int i = 0; i < values.length; i++) {
			if (values[i].key.equals(normalized) || ENGLISH[i].equals(normalized)) return values[i];
		}
		return UNKNOWN;
	}

	//Acentos fuera, guiones y espacios fuera, minúsculas: "Gargantuesco", "gargantuesco" y "GARGANTUESCO"
	//son la misma palabra, y "no-muerto" enseñó en CreatureType que el guion aparece solo.
	private static String normalize(String raw) {
		String decomposed = Normalizer.normalize(raw.trim().toLowerCase(Locale.ROOT), Normalizer.Form.NFD);
		return decomposed.replaceAll("\\p{M}", "").replaceAll("[\\s_-]", "");
	}
}

