import glob,os,re
m={'jugadores':'players','archivo':'file','peso':'weight','personaje':'character','monstruoId':'monsterId','hechizoId':'spellId','dado':'dice','turnos':'turns','titulo':'title','tipoDano':'damageType','rasgoId':'traitId','pacto':'pactType','modo':'mode','maximo':'max','actual':'current','filtro':'filter','expresion':'rollExpression','estructura':'structure','estado':'state','entidad':'entity','encuentroId':'encounterId','donde':'position','armaId':'weaponId','afinidad':'affinity','radio':'radius','habDano':'damageAbility','habAtaque':'attackAbility','ia':'ai'}
tot={}
for f in glob.glob('**/*.java',recursive=True):
    if 'build' in f.split(os.sep): continue
    s=open(f,encoding='utf-8',newline='').read(); t=s
    for a,b in m.items():
        n=t.count('"%s"'%a)
        if n: t=t.replace('"%s"'%a,'"%s"'%b); tot[a]=tot.get(a,0)+n
    if t!=s: open(f,'w',encoding='utf-8',newline='').write(t)
print(tot)
PYEOF

