import re, glob, os, sys
sys.stdout.reconfigure(encoding='utf-8')
es = re.compile(r'\b(jugadores?|archivos?|cantidad|tipo|afinidad|pacto|hoja|dado|nombre|celdas?|filas?|cuerpo|bloque|etiqueta|estado|sinRegistrar|espacioDeNombres|habAtaque|unBloque\w+|nivel|raza|pieza|vara|bicho|tirada|dano|ataque|hechizo|clase|rasgos?|objeto|arma|vida|condicion(es)?|descanso)\b')
for f in sorted(glob.glob('**/*.java', recursive=True)):
    if 'build' in f.split(os.sep):
        continue
    for i, l in enumerate(open(f, encoding='utf-8'), 1):
        c = re.sub(r'"(?:[^"\\]|\\.)*"', '""', l)
        c = re.sub(r'//.*$', '', c)
        if re.match(r'\s*(\*|/\*)', c):
            continue
        m = es.findall(c)
        if m:
            print(f.replace(chr(92), '/').split('/')[-1] + ':' + str(i), [x[0] for x in m][:4], l.strip()[:120])

