"""Usage: python vocab.py <plan.json>
plan.json: {"words": {"OLD": "NEW"}, "quoted": {"old": "new"}, "exclude": ["path fragments"], "globs": [...optional]}
 - words: whole-word, case-sensitive replace in code AND comments of .java files
 - quoted: exact "old" string literal -> "new" in .java/.json/.py/.md (only when the literal is exactly that)
"""
import re, glob, os, sys, json
sys.stdout.reconfigure(encoding='utf-8')
ROOT = r'C:\Users\DanCastello\Documents\GitHub\dndsheets'
plan = json.load(open(sys.argv[1], encoding='utf-8'))
words = plan.get('words', {})
quoted = plan.get('quoted', {})
exclude = plan.get('exclude', []) + ['/build/', '/.gradle/', '/lang/es_', '/graphify-out/', '/.git/', '/runClient/', '/runServer/', '/runGameTest/']
dry = '--dry' in sys.argv
counts = {}
for dp, dn, fn in os.walk(ROOT):
    dn[:] = [d for d in dn if d not in ('build', '.gradle', '.git', 'graphify-out', 'runClient', 'runServer', 'runGameTest', 'node_modules', '.scratch')]
    for name in fn:
        ext = os.path.splitext(name)[1]
        if ext not in ('.java', '.json', '.py', '.md', '.toml'):
            continue
        p = os.path.join(dp, name)
        pn = p.replace(os.sep, '/')
        if any(e in pn for e in exclude):
            continue
        try:
            s = open(p, encoding='utf-8', newline='').read()
        except Exception:
            continue
        t = s
        if ext == '.java':
            for a, b in words.items():
                pat = re.compile(r'\b' + re.escape(a) + r'\b')
                n = len(pat.findall(t))
                if n:
                    t = pat.sub(b, t)
                    counts[a] = counts.get(a, 0) + n
        for a, b in quoted.items():
            for q in ('"',):
                o = q + a + q
                n = t.count(o)
                if n:
                    t = t.replace(o, q + b + q)
                    counts['"' + a + '"'] = counts.get('"' + a + '"', 0) + n
        if t != s and not dry:
            open(p, 'w', encoding='utf-8', newline='').write(t)
for k, v in counts.items():
    print(v, k)

