    for v in es.values(): es_w |= words(v)
    for v in en.values(): en_w |= words(v)
spanish = es_w - en_w
# also words that look english-ish in the es file are dropped; keep only reasonably long ones
spanish = {w for w in spanish if len(w) >= 3}
