            if s.startswith(('gui.', 'chat.', 'content.', 'dndsheets:', 'minecraft:', 'item.', 'key.', 'tooltip.', 'button:')): continue
            ws = re.findall(r"[a-záéíóúñü]{3,}", s.lower())
            hit = [w for w in ws if w in spanish]
            if hit and (len(hit) >= 1) and (' ' in s or any(c in s for c in 'áéíóúñ¿¡')):
                res.setdefault(rel, []).append((i, s[:100], hit[:3]))
for k, v in res.items():
    print('##', k, len(v))
    for i, s, h in v[:8]:
        print('  ', i, repr(s), h)
print(sum(len(v) for v in res.values()))

