import os, sys, glob
sys.stdout.reconfigure(encoding='utf-8')
ROOT = 'C:/Users/DanCastello/Documents/GitHub/dndsheets/'
names = {'rayo_de_ejemplo': 'example_ray', 'centinela_de_ejemplo': 'example_sentinel', 'hacha_de_ejemplo': 'example_axe',
         'rasgo_de_ejemplo': 'example_trait', 'preset_de_ejemplo': 'example_preset', 'encuentro_de_ejemplo': 'example_encounter',
         'dote_de_ejemplo': 'example_feat', 'miaddon': 'myaddon', 'ejemplo.json': 'example.json', '"ejemplo"': '"example"'}
skip_dirs = {'build', '.gradle', '.git', 'graphify-out', 'runClient', 'runServer', 'runGameTest', 'node_modules', '.claude'}
n = 0
for dp, dn, fn in os.walk(ROOT):
    dn[:] = [d for d in dn if d not in skip_dirs]
    for f in fn:
        if os.path.splitext(f)[1] not in ('.java', '.json', '.md', '.gradle', '.py', '.toml', '.mcmeta'):
            continue
        p = os.path.join(dp, f)
        if '/lang/es_' in p.replace(os.sep, '/'):
            continue
        try:
            s = open(p, encoding='utf-8', newline='').read()
        except Exception:
            continue
        t = s
        for a, b in names.items():
            t = t.replace(a, b)
        if t != s:
            open(p, 'w', encoding='utf-8', newline='').write(t)
            n += 1
print('text files updated:', n)
# rename files and dirs (deepest first)
for dp, dn, fn in os.walk(ROOT + 'src/test/resources', topdown=False):
    for x in fn + dn:
        y = x
        for a, b in names.items():
            y = y.replace(a, b)
        if y != x:
            os.rename(os.path.join(dp, x), os.path.join(dp, y))
for f in glob.glob(ROOT + 'test/dndsheets/*/ejemplo.json'):
    os.rename(f, f.replace('ejemplo.json', 'example.json'))
print('renamed')

