"""python blocks2.py file... : print maximal comment-line runs that contain Spanish, as 'start-end' + text"""
import re, sys
sys.stdout.reconfigure(encoding='utf-8')
ROOT = 'C:/Users/DanCastello/Documents/GitHub/dndsheets/'
sw = set("el la los las de del que para con una un por se no es en al su sus lo como pero si sin sobre entre cuando ya más esta este esto cada todo todos hay puede pueden debe solo también fue era son ser está están ni o y aunque porque mientras donde cuyo así hasta desde".split())
def sc(l):
    return sum(1 for w in re.findall(r"[a-záéíóúñ]+", l.lower()) if w in sw) + (2 if re.search(r'[áéíóúñ¿¡]', l) else 0)
def is_comment(l):
    return bool(re.match(r'\s*(#|//|\*|/\*)', l))
for f in sys.argv[1:]:
    L = open(ROOT + f, encoding='utf-8', errors='replace').read().split('\n')
    print('#####', f)
    i = 0
    while i < len(L):
        if is_comment(L[i]):
            j = i
            while j + 1 < len(L) and is_comment(L[j + 1]):
                j += 1
            if any(sc(l) >= 2 for l in L[i:j + 1]):
                print('[%d-%d]' % (i + 1, j + 1))
                for l in L[i:j + 1]:
                    print(l.rstrip())
            i = j + 1
        else:
            if sc(L[i]) >= 2 and not is_comment(L[i]):
                print('[%d] (code) %s' % (i + 1, L[i].rstrip()))
            i += 1

