import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ab import apply

apply('gradle.properties', [(2, 12, '''
# The wrapper is no longer 8.1.1 but 8.8, so Gradle DOES run on Java 21 (support arrived in 8.5).
# It was bumped because 8.1.1's ASM can't read Java 21 classes, and that stopped being a rare case:
# any modern plugin drags some in, and ModPublisher (the publishing one) wouldn't even let the
# build evaluate. See the comment of the `buildscript` block in build.gradle.
#
# With 8.8, setting org.gradle.java.home in YOUR ~/.gradle/gradle.properties (never here: a versioned
# absolute path breaks the build on any other machine) goes from required to optional. The toolchain is still
# 17 —java.toolchain.languageVersion in build.gradle, which is what Forge 1.20.1 asks for—; the only thing
# that changes is which JVM Gradle can run on. Still UNTESTED without that pin.
# Disabled to prevent a hung Gradle daemon from keeping the .jar/.class files in
# build/ locked on Windows between runs (ForgeGradle reobfuscates and repackages the jar on every build).
''')])

apply('settings.gradle', [
(10, 12, '''
// ModPublisher (the `publishMod` task of build.gradle). It is NOT in Gradle's plugin portal: it is
// published only on its author's maven, so without this entry the build's `plugins {}` doesn't
// even evaluate.
'''),
(26, 28, '''
// Separate addon with its own modid ("dndsheets_dungeon"), a HARD dependency of the core: see
// dungeon/build.gradle and PROJECT_CONTEXT.md (core/addons split). It doesn't share a sourceSet with the
// core — it compiles against its jar via `implementation project(':')`.
'''),
(31, 33, '''
// Separate addon with its own modid ("dndsheets_species"), a HARD dependency of the core AND of Origins
// (see species/build.gradle): Origins picks the race, this addon applies the Ability Score Increase
// and the SRD traits with dndsheets' own code — Origins never writes the sheet directly.
'''),
])

apply('species/build.gradle', [
(26, 31, '''
// Same as dungeon/build.gradle: the addon doesn't start on its own, it needs the core. Origins
// is NOT added here on purpose — it uses real Mixins on vanilla classes (verified
// with javap on origins-forge-1.20.1-1.10.0.9-all.jar), and this project already documented
// in the root build.gradle why no mod with mixins loads in runClient with parchment mappings
// (SRG vs. real names). This integration is tested in a real install,
// just like Curios and Patchouli.
'''),
(60, 61, '''
// Only for Origins. exclusiveContent: no other artifact is looked up here, so if this maven
// is down it doesn't drag down the rest of the build (same criterion as Curios' maven in the root).
'''),
(73, 78, '''
// Origins is downloaded; Apoli has NO coordinate of its own for Forge on any maven (verified: on Modrinth
// it gives 404, and on CurseForge the version would have to be pinned by hand separately). It isn't needed: it travels
// INSIDE Origins' jar as jarjar (META-INF/jarjar/apoli-forge-*.jar), and a nested jar does NOT enter
// javac's classpath. It is extracted from that same jar instead of versioning a loose copy, which is what
// used to be in dependencies/: this way the Apoli version compiled against can't
// drift out of sync with the Origins that brings it, because it comes literally from inside.
'''),
(81, 82, '''
//extendsFrom and not "compileOnly configurations.originsDist": Gradle 8 forbids passing a Configuration
//as a dependency. This way the coordinate is written only once.
'''),
(97, 98, '''
// HARD dependency on the core (see dungeon/build.gradle for the same pattern): it compiles against its
// sourceSet, not a separately published jar.
'''),
(101, 106, '''
// Origins/Apoli: compileOnly ONLY. At runtime the mod must be installed so that
// /dndspecies sync has something to read (see OriginBridge), but it can't be tested in
// runClient (mixins + parchment, see comment above) so there's no point dragging it in as
// runtimeOnly here. jl3m2lR9 = Origins (Forge); vynFXywM = its version 1.20.1-1.10.0.9, the same one that
// used to live by hand in dependencies/. It is pinned by version id, not by range: a new version of
// Origins can't change under our feet what compiles here.
'''),
(119, 120, '''
// Same pattern as the core and dungeon: pure logic (RaceRegistry.apply) tested standing up, without the
// Forge runtime.
'''),
], [("//Aplana: sin esto reproduce META-INF/jarjar/.", "//Flattens: without this it reproduces META-INF/jarjar/.")])

apply('dungeon/build.gradle', [
(26, 28, '''
// The addon doesn't start on its own — it needs the core loaded in the same development
// client. A direct source of the root project's sourceSet, not the published jar:
// this way a change in either module shows up without having to compile the other.
'''),
(59, 62, '''
// HARD dependency on the core: the dungeon toolkit isn't really an independent mod,
// it only touches three things of the core (DndsheetsMod.LOGGER/PRETTY_GSON/MODID, DndPaths, TomeButton) and
// extends its shared GUI framework (SmallFormScreen/ListPickerScreen/ModalDialogScreen/
// GuiStyle). It compiles against the root project's sourceSet, not a separately published jar.
'''),
(74, 75, '''
// Same pattern as the core (see the root build.gradle): pure logic (DungeonManager.buildPoolJsons,
// GridToStructure) tested standing up, without the Forge runtime.
'''),
])

apply('.gitignore', [
