import re, sys
sys.stdout.reconfigure(encoding='utf-8')
ROOT = 'C:/Users/DanCastello/Documents/GitHub/dndsheets/'
sw = set("el la los las de del que para con una un por se no es en al su sus lo como pero si sin sobre entre cuando ya más esta este esto cada todo todos hay puede pueden debe solo también fue era son ser está están ni o y aunque porque mientras donde cuyo así hasta desde".split())
esw = set("ejemplo hoja hojas dado tirada personaje nivel clase hechizo hechizos monstruo arma armas jugador jugadores mazmorra iconos icono textura pestana pestaña fondo marco pergamino cuero tomo escuadras borde relleno ancho alto columna fila filas rejilla veteado sombra luz grano".split())
def sc(l):
    ws = re.findall(r"[a-záéíóúñ]+", l.lower())
    return sum(1 for w in ws if w in sw) + sum(1 for w in ws if w in esw) + (2 if re.search(r'[áéíóúñ¿¡]', l) else 0)
for f in sys.argv[1:]:
    L = open(ROOT + f, encoding='utf-8', errors='replace').read().split('\n')
    flagged = [i for i, l in enumerate(L) if sc(l) >= 2]
    print('#####', f, len(L), 'lines;', len(flagged), 'flagged')
    runs = []
    for i in flagged:
        if runs and i - runs[-1][1] <= 3:
            runs[-1][1] = i
        else:
            runs.append([i, i])
    for a, b in runs:
        print('[%d-%d]' % (a + 1, b + 1))
        for l in L[a:b + 1]:
            print(l.rstrip())

