import com.sun.source.tree.*;
import com.sun.source.util.*;
import javax.tools.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;

public class Scan {
    public static void main(String[] args) throws Exception {
        JavaCompiler jc = ToolProvider.getSystemJavaCompiler();
        StandardJavaFileManager fm = jc.getStandardFileManager(null, null, null);
        List<Path> files = new ArrayList<>();
        for (String root : args) {
            try (Stream<Path> s = Files.walk(Path.of(root))) {
                s.filter(p -> p.toString().endsWith(".java")).forEach(files::add);
            }
        }
        for (Path f : files) {
            String norm = f.toString().replace('\\', '/');
            if (norm.contains("/build/") || norm.contains("/src/test/")) continue;
            JavacTask task = (JavacTask) jc.getTask(null, fm, d -> {}, List.of("-proc:none"), null, fm.getJavaFileObjects(f.toFile()));
            SourcePositions sp = Trees.instance(task).getSourcePositions();
            for (CompilationUnitTree cu : task.parse()) {
                LineMap lm = cu.getLineMap();
                new TreeScanner<Void, Void>() {
                    boolean hasNullable(MethodTree m) {
                        return m.getModifiers().getAnnotations().stream().anyMatch(a -> a.getAnnotationType().toString().endsWith("Nullable"));
                    }
                    @Override public Void visitMethod(MethodTree m, Void v) {
                        Tree rt = m.getReturnType();
                        boolean ok = rt != null && !(rt instanceof PrimitiveTypeTree) && m.getBody() != null && !hasNullable(m);
                        if (ok && returnsNull(m.getBody())) {
                            long pos = sp.getStartPosition(cu, m);
                            System.out.println(norm + "|" + lm.getLineNumber(pos) + "|" + m.getName());
                        }
                        return super.visitMethod(m, v);
                    }
                    boolean returnsNull(Tree body) {
                        boolean[] found = {false};
                        new TreeScanner<Void, Void>() {
                            @Override public Void visitLambdaExpression(LambdaExpressionTree t, Void v) { return null; }
                            @Override public Void visitClass(ClassTree t, Void v) { return null; }
                            @Override public Void visitReturn(ReturnTree t, Void v) {
                                if (nullish(t.getExpression())) found[0] = true;
                                return null;
                            }
                        }.scan(body, null);
                        return found[0];
                    }
                    boolean nullish(ExpressionTree e) {
                        if (e == null) return false;
                        if (e instanceof ParenthesizedTree p) return nullish(p.getExpression());
                        if (e instanceof LiteralTree l) return l.getValue() == null;
                        if (e instanceof ConditionalExpressionTree c) return nullish(c.getTrueExpression()) || nullish(c.getFalseExpression());
                        return false;
                    }
                }.scan(cu, null);
            }
        }
    }
}

